const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const files=['app.js','engine.js','stems.js','panels.js','sync-tempo-handoff.js','stem-activation-harness.js','fx-tempo-capture-worklet.js'];
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
async function identities(){const r={};for(const f of files){const response=await fetch(f,{cache:'no-store'});assert(response.ok,'Missing '+f);r[f]=await hash(await response.arrayBuffer());}return r;}
async function until(fn,label,ms=90000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function base64(b){let s='';for(let i=0;i<b.length;i+=16384)s+=String.fromCharCode(...b.subarray(i,i+16384));return btoa(s);}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},button=(i,a)=>`[data-action="${a}"][data-deck="${i}"]`;
let app;
async function run(){const pitched=new URL(location.href).searchParams.has('pitch');const {engine,state}=app,d=state.decks[0],track=d.track,witnesses=[];const r={startedAt:new Date().toISOString(),scope:'Actual browser production Play→local SCNet preparation/completed cache→attach during playback→Stem pads→Stop. Generated8sec330Hz-left/550Hz-right input; physical graph muted. Not musical separation/listening/native/controller/vendor/full-parity acceptance.',criteria:{captureSeconds:pitched?4:12,maximumNearZeroRunSeconds:.001,minimum10msRMSRatio:.85,maximumAdjacentJump:.03,nearZeroAbsolute:1e-7},progress:[],errors:[],checks:[]};$('#activation-run').disabled=true;
 async function capture(id,seconds){return Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM timeout')),seconds*1000+10000);w.port.onmessage=({data})=>{if(data.type==='done'&&data.id===id){clearTimeout(timer);resolve(data);}};w.port.postMessage({type:'capture',id,frames:Math.round(seconds*engine.ctx.sampleRate)});})));}
 async function retain(raw){const result=[];for(const p of raw){const b=new Uint8Array(p.data.buffer);result.push({startFrame:p.startFrame,frames:p.data.length,sha256:await hash(b),base64:base64(b)});}return result;}
 try{r.sourceBefore=await identities();engine.init();engine.audioMonitor.mutePhysical(true);await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await until(()=>!state.analysis,'Initial analysis');for(const x of state.decks)engine.pause(x);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(x=>(x.track?.bpm||120)*x.rate),state.fxTempo);
  const sr=44100,b=engine.ctx.createBuffer(2,sr*8,sr);for(let ch=0;ch<2;ch++)for(let i=0;i<b.length;i++)b.getChannelData(ch)[i]=.12*Math.sin(2*Math.PI*(ch?550:330)*i/sr);Object.assign(track,{duration:8,bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],analyzed:true});delete track.stemJob;Object.assign(d,{position:0,rate:pitched?1.1:1,keylock:pitched,keyShift:0,reverse:false,loop:!pitched,loopIn:0,loopOut:4,slip:false,stemSlip:'off',sync:false,mode:'INT',stems:[true,true,true,true],stemFX:[false,false,false,false]});engine.clearDeckScratchCache(0);engine.stemBuffers.delete(track.id);engine.buffers.set(track.id,b);engine.mix(0,'level',.8);state.selected=track.id;r.originalHashes=await Promise.all([0,1].map(ch=>hash(b.getChannelData(ch).buffer)));r.sampleRate=engine.ctx.sampleRate;r.transport={rate:d.rate,keylock:d.keylock,loop:d.loop};
  await engine.ctx.audioWorklet.addModule(new URL('./fx-tempo-capture-worklet.js',import.meta.url));const split=engine.ctx.createChannelSplitter(2);engine.masterOutput.output.connect(split);for(let ch=0;ch<2;ch++){const w=new AudioWorkletNode(engine.ctx,'open-play-fx-tempo-capture-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,ch);w.connect(engine.ctx.destination);witnesses.push(w);}
  click(button(0,'tab')+'[data-tab="Stems"]');click(button(0,'play'));await until(()=>d.playing&&!d.processing,'Play');await sleep(150);const old=engine.voices.get(0),oldClock=engine.voiceClock(d,old);r.initialClock={audioTime:engine.ctx.currentTime,position:engine.position(d)};
  click(button(0,'stemPrepare'));const output=$('#stems-state'),observer=new MutationObserver(()=>r.progress.push({audioTime:engine.ctx.currentTime,message:output.textContent,playing:d.playing,processing:d.processing}));observer.observe(output,{childList:true,characterData:true,subtree:true});const recording=capture(1,r.criteria.captureSeconds);await sleep(300);r.prepareAt=engine.ctx.currentTime;click('#stems-queue');$('#activation-status').textContent='Preparing and capturing continuous output…';await until(()=>track.stemJob&&engine.stemBuffers.has(track.id)&&!$('#stems-queue').disabled,'SCNet activation');r.activatedAt=engine.ctx.currentTime;r.activation={playing:d.playing,processing:d.processing,voiceChanged:old!==engine.voices.get(0),originalExpectedPosition:oldClock(engine.ctx.currentTime),actualPosition:engine.position(d),loop:d.loop,model:track.stemModel,sourceCount:engine.voices.get(0)?.sources?.length};r.job=await(await fetch('/api/stems/'+track.stemJob)).json();assert(r.job.model==='SCNet-large official'&&r.job.state==='complete','Real SCNet exports required');assert(d.playing&&!d.processing,'Activation stopped playback');assert(r.activatedAt-r.prepareAt<r.criteria.captureSeconds-1,'Activation happened outside the bounded capture');r.pcm=await retain(await recording);observer.disconnect();r.checks.push('Actual local SCNet completed job attached four buffers while playback remained requested');click('#modal-close');
  for(let i=0;i<4;i++)click(button(0,'pad')+`[data-pad="${i}"]`);await sleep(150);r.muted={enabled:[...d.stems],pcm:await retain(await capture(2,.15))};assert(d.stems.every(x=>!x),'All four pad mutes');for(let i=0;i<4;i++)click(button(0,'pad')+`[data-pad="${i}"]`);await sleep(150);r.restored={enabled:[...d.stems],playing:d.playing,pcm:await retain(await capture(3,.15))};click(button(0,'play'));await until(()=>!d.playing,'Stop');await sleep(150);r.stopped={playing:d.playing,pcm:await retain(await capture(4,.15))};r.finalOriginalHashes=await Promise.all([0,1].map(ch=>hash(engine.buffers.get(track.id).getChannelData(ch).buffer)));r.originalUnchanged=JSON.stringify(r.originalHashes)===JSON.stringify(r.finalOriginalHashes);assert(r.originalUnchanged,'Original decoded audio changed');
 }catch(e){r.errors.push({message:e.message,stack:e.stack});}finally{for(const x of state.decks)engine.pause(x);for(const w of witnesses){w.disconnect();w.port.close();}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.workflowCompleted=!r.errors.length&&!!r.stopped&&r.sourceStable;r.finishedAt=new Date().toISOString();const text=JSON.stringify(r,null,2);$('#activation-original').textContent=text;$('#activation-results').textContent=JSON.stringify({...r,pcm:r.pcm?.map(p=>({...p,base64:'Retained in original'})),muted:r.muted?{enabled:r.muted.enabled}:null,restored:r.restored?{enabled:r.restored.enabled}:null,stopped:r.stopped?{playing:r.stopped.playing}:null},null,2);const a=$('#activation-download');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download='stem-activation-original.json';a.hidden=false;$('#activation-status').textContent=r.workflowCompleted?'Capture retained; independent continuity inspection required; stopped':'Failed: '+r.errors.map(e=>e.message).join('; ');}}
$('#activation-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;$('#activation-run').disabled=false;$('#activation-status').textContent='Ready';}boot().catch(e=>$('#activation-status').textContent=e.message);
